-- Carta de demostración "Doris Restaurant · Valparaíso" (Barrio Puerto; IG @restaurantdorisvalpo, WhatsApp +56 9 3177 3093),
-- para mostrársela al restaurante. Transcrita de su carta ilustrada (2 láminas, 12-11-2026) con sus precios exactos en CLP:
-- 6 categorías y 29 platos/bebidas. Nombres en español; descripciones traducidas a inglés, portugués, francés, alemán,
-- italiano, chino y holandés. "Todos nuestros platos incluyen consomé o ensalada, pebre y pan" va como opción Acompañamiento.
-- Las variantes de la carta (relleno de empanada, preparación de la reineta, carne a lo pobre, tipo de chorrillana, papas
-- $4.000/$7.000, vinos $6.000/$8.000/$10.000) van como opciones del plato. Logo nuevo ilustrado: public/demo/doris/logo.png.
-- Diseño "Pintor" (puerto pintado de Valparaíso) en rojo y crema como su carta. El diseño necesita la migración 0037: este
-- archivo la incluye (solo amplía la lista de diseños permitidos), así que funciona aunque 0037 no se haya ejecutado.
-- Se puede ejecutar más de una vez: borra y vuelve a crear la carta de la demo (categorías y platos), sin tocar nada más.

alter table public.restaurantes drop constraint if exists restaurantes_tema_check;
alter table public.restaurantes
  add constraint restaurantes_tema_check
  check (tema in (
    'clasico', 'noir', 'esmeralda', 'street', 'retro',
    'bistro', 'veggie', 'forno', 'oriente', 'neon',
    'tropical', 'jugos', 'batidos', 'gala', 'vitrina', 'cinta', 'trattoria', 'kraft', 'madera', 'coctel', 'revista',
    'barista', 'latte', 'origen', 'grano', 'caramelo', 'libreta', 'muro', 'porteno',
    'pintor'
  ));

do $$
declare
  rid uuid;
  cid uuid;
begin
  select id into rid from public.restaurantes where slug = 'doris';
  if rid is null then
    insert into public.restaurantes (slug, nombre) values ('doris', 'Doris Restaurant') returning id into rid;
  end if;
  update public.restaurantes set
    nombre = 'Doris Restaurant',
    descripcion = 'Cocina porteña casera en el Barrio Puerto de Valparaíso · Todos nuestros platos incluyen consomé o ensalada, pebre y pan · Ceviche de reineta viernes y sábado · Reserva tu parrillada para compartir por WhatsApp',
    logo_url = '/demo/doris/logo.png',
    tema = 'pintor',
    color_primario = '#b8262c',
    color_fondo = '#f3ead9',
    moneda = 'CLP',
    plan = 'pro',
    whatsapp = '56931773093',
    idiomas = array['en', 'pt', 'fr', 'de', 'it', 'zh', 'nl'],
    traducciones = '{"en": {"descripcion": "Homestyle port cooking in Valparaíso''s Barrio Puerto · All our dishes include consommé or salad, pebre and bread · Pomfret ceviche on Fridays and Saturdays · Book your sharing grill platter on WhatsApp"}, "pt": {"descripcion": "Cozinha caseira do porto no Barrio Puerto de Valparaíso · Todos os pratos incluem consomê ou salada, pebre e pão · Ceviche de reineta às sextas e sábados · Reserve sua parrillada para compartilhar pelo WhatsApp"}, "fr": {"descripcion": "Cuisine maison du port, Barrio Puerto de Valparaíso · Tous nos plats incluent consommé ou salade, pebre et pain · Ceviche de reineta le vendredi et le samedi · Réservez votre grillade à partager sur WhatsApp"}, "de": {"descripcion": "Hausmannskost aus dem Hafen im Barrio Puerto von Valparaíso · Alle Gerichte mit Kraftbrühe oder Salat, Pebre und Brot · Reineta-Ceviche freitags und samstags · Grillplatte zum Teilen per WhatsApp reservieren"}, "it": {"descripcion": "Cucina casalinga del porto nel Barrio Puerto di Valparaíso · Tutti i piatti includono consommé o insalata, pebre e pane · Ceviche di reineta venerdì e sabato · Prenota la tua grigliata da condividere su WhatsApp"}, "zh": {"descripcion": "瓦尔帕莱索港口区的家常港口菜 · 所有菜品均附清汤或沙拉、智利辣酱和面包 · 周五、周六供应鲳鱼酸橘汁腌鱼 · 可通过 WhatsApp 预订分享烤肉拼盘"}, "nl": {"descripcion": "Huisgemaakte havenkeuken in Barrio Puerto, Valparaíso · Alle gerechten met bouillon of salade, pebre en brood · Reineta-ceviche op vrijdag en zaterdag · Reserveer je grillschotel om te delen via WhatsApp"}}'::jsonb,
    ajustes = ajustes || '{"pais": "CL", "zona_horaria": "America/Santiago", "imagenes_defecto": true, "redes": {"instagram": "https://www.instagram.com/restaurantdorisvalpo/", "facebook": "https://www.facebook.com/restaurantdoris/"}, "estaciones": ["Cocina", "Barra"]}'::jsonb
  where id = rid;

  delete from public.platos where restaurante_id = rid;
  delete from public.categorias where restaurante_id = rid;
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Empanadas fritas', 0, '{"en": {"nombre": "Fried empanadas"}, "pt": {"nombre": "Empanadas fritas"}, "fr": {"nombre": "Empanadas frites"}, "de": {"nombre": "Frittierte Empanadas"}, "it": {"nombre": "Empanadas fritte"}, "zh": {"nombre": "炸馅饼"}, "nl": {"nombre": "Gefrituurde empanada''s"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Empanada de queso', 'Empanada frita rellena de queso derretido.', 2500, '{}', 0, false, '{"en": {"descripcion": "Fried empanada filled with melted cheese."}, "pt": {"descripcion": "Empanada frita recheada com queijo derretido."}, "fr": {"descripcion": "Empanada frite fourrée au fromage fondu."}, "de": {"descripcion": "Frittierte Empanada mit geschmolzenem Käse."}, "it": {"descripcion": "Empanada fritta ripiena di formaggio fuso."}, "zh": {"descripcion": "炸馅饼，内馅为融化的奶酪。"}, "nl": {"descripcion": "Gefrituurde empanada gevuld met gesmolten kaas."}}'::jsonb, '[]'::jsonb, 'empanada');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Empanada de marisco', 'Empanada frita. Elige el relleno: marisco, jaiba queso, ostión queso, camarón queso o marisco queso.', 4000, '{}', 1, false, '{"en": {"descripcion": "Fried empanada. Choose the filling: seafood, crab & cheese, scallop & cheese, shrimp & cheese or seafood & cheese."}, "pt": {"descripcion": "Empanada frita. Escolha o recheio: frutos do mar, siri com queijo, vieira com queijo, camarão com queijo ou frutos do mar com queijo."}, "fr": {"descripcion": "Empanada frite. Au choix : fruits de mer, crabe-fromage, Saint-Jacques-fromage, crevettes-fromage ou fruits de mer-fromage."}, "de": {"descripcion": "Frittierte Empanada. Füllung nach Wahl: Meeresfrüchte, Krabbe & Käse, Jakobsmuschel & Käse, Garnele & Käse oder Meeresfrüchte & Käse."}, "it": {"descripcion": "Empanada fritta. Scegli il ripieno: frutti di mare, granchio e formaggio, capasanta e formaggio, gamberi e formaggio o frutti di mare e formaggio."}, "zh": {"descripcion": "炸馅饼，馅料可选：海鲜、蟹肉芝士、扇贝芝士、虾仁芝士或海鲜芝士。"}, "nl": {"descripcion": "Gefrituurde empanada. Kies de vulling: zeevruchten, krab & kaas, sint-jakobsschelp & kaas, garnaal & kaas of zeevruchten & kaas."}}'::jsonb, '[{"nombre": "Relleno", "min": 1, "max": 1, "valores": [{"nombre": "Marisco", "precio": 0}, {"nombre": "Jaiba queso", "precio": 0}, {"nombre": "Ostión queso", "precio": 0}, {"nombre": "Camarón queso", "precio": 0}, {"nombre": "Marisco queso", "precio": 0}]}]'::jsonb, 'empanada');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Platos principales', 1, '{"en": {"nombre": "Main courses"}, "pt": {"nombre": "Pratos principais"}, "fr": {"nombre": "Plats principaux"}, "de": {"nombre": "Hauptgerichte"}, "it": {"nombre": "Piatti principali"}, "zh": {"nombre": "主菜"}, "nl": {"nombre": "Hoofdgerechten"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Merluza frita con 2 agregados', 'Merluza frita y crujiente, con dos agregados a elección. Incluye consomé o ensalada, pebre y pan.', 7500, '{}', 0, false, '{"en": {"descripcion": "Crispy fried hake with two sides of your choice. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Pescada frita e crocante, com dois acompanhamentos à escolha. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Merlu frit et croustillant, avec deux accompagnements au choix. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Knusprig frittierter Seehecht mit zwei Beilagen nach Wahl. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Nasello fritto e croccante, con due contorni a scelta. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "香脆炸无须鳕，可任选两份配菜。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Krokant gefrituurde heek met twee bijgerechten naar keuze. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Bistec con arroz y papas fritas', 'Bistec a la plancha con arroz y papas fritas. Incluye consomé o ensalada, pebre y pan.', 7500, '{}', 1, false, '{"en": {"descripcion": "Grilled beef steak with rice and French fries. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Bife grelhado com arroz e batatas fritas. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Steak grillé avec riz et frites. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Gegrilltes Rindersteak mit Reis und Pommes frites. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Bistecca alla piastra con riso e patatine fritte. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "铁板牛排配米饭和薯条。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Gegrilde biefstuk met rijst en friet. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'vacuno');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Calugas de merluza (10) con 1 agregado', '10 trozos de merluza apanada y frita, con un agregado a elección. Incluye consomé o ensalada, pebre y pan.', 8500, '{}', 2, false, '{"en": {"descripcion": "10 breaded fried hake strips with one side of your choice. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "10 iscas de pescada empanada e frita, com um acompanhamento à escolha. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "10 bâtonnets de merlu pané et frit, avec un accompagnement au choix. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "10 panierte, frittierte Seehechtstücke mit einer Beilage nach Wahl. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "10 bocconcini di nasello impanato e fritto, con un contorno a scelta. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "10块裹粉炸无须鳕鱼条，可任选一份配菜。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "10 gepaneerde, gefrituurde heekreepjes met één bijgerecht naar keuze. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Reineta frita, vapor o a la mantequilla con 2 agregados', 'Reineta como prefieras (frita, al vapor o a la mantequilla), con dos agregados a elección. Incluye consomé o ensalada, pebre y pan.', 9500, '{}', 3, false, '{"en": {"descripcion": "Pomfret (reineta) fried, steamed or in butter, with two sides of your choice. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Reineta frita, no vapor ou na manteiga, com dois acompanhamentos à escolha. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Reineta (castagnole) frite, vapeur ou au beurre, avec deux accompagnements au choix. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Reineta (Brachsenmakrele) frittiert, gedämpft oder in Butter, mit zwei Beilagen nach Wahl. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Reineta fritta, al vapore o al burro, con due contorni a scelta. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "智利鲳鱼（reineta），可选油炸、清蒸或黄油煎，配两份自选配菜。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Reineta (braam) gefrituurd, gestoomd of in boter, met twee bijgerechten naar keuze. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Preparación", "min": 1, "max": 1, "valores": [{"nombre": "Frita", "precio": 0}, {"nombre": "Al vapor", "precio": 0}, {"nombre": "A la mantequilla", "precio": 0}]}, {"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Reineta frita, vapor o a la mantequilla con papas fritas', 'Reineta como prefieras (frita, al vapor o a la mantequilla), con papas fritas. Incluye consomé o ensalada, pebre y pan.', 12500, '{}', 4, false, '{"en": {"descripcion": "Pomfret (reineta) fried, steamed or in butter, with French fries. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Reineta frita, no vapor ou na manteiga, com batatas fritas. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Reineta (castagnole) frite, vapeur ou au beurre, avec des frites. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Reineta (Brachsenmakrele) frittiert, gedämpft oder in Butter, mit Pommes frites. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Reineta fritta, al vapore o al burro, con patatine fritte. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "智利鲳鱼（reineta），可选油炸、清蒸或黄油煎，配薯条。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Reineta (braam) gefrituurd, gestoomd of in boter, met friet. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Preparación", "min": 1, "max": 1, "valores": [{"nombre": "Frita", "precio": 0}, {"nombre": "Al vapor", "precio": 0}, {"nombre": "A la mantequilla", "precio": 0}]}, {"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Paila Marina normal', 'Sopa caliente de mariscos y pescado servida en paila, clásica de la costa chilena. Incluye consomé o ensalada, pebre y pan.', 12000, '{}', 5, false, '{"en": {"descripcion": "Hot seafood and fish soup served in a clay-style bowl, a classic of the Chilean coast. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Sopa quente de frutos do mar e peixe servida na tigela, clássica do litoral chileno. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Soupe chaude de fruits de mer et de poisson, grand classique de la côte chilienne. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Heiße Suppe mit Meeresfrüchten und Fisch, ein Klassiker der chilenischen Küste. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Zuppa calda di frutti di mare e pesce, classico della costa cilena. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "热腾腾的海鲜鱼汤，盛在砂锅中，智利海岸经典菜。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Hete soep van zeevruchten en vis, een klassieker van de Chileense kust. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'sopa');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Paila Marina Doris', 'Nuestra paila marina de la casa, premiada como la mejor paila del Barrio Puerto. Incluye consomé o ensalada, pebre y pan.', 14000, '{"recomendado"}', 6, true, '{"en": {"descripcion": "Our house seafood soup, awarded best paila marina in Barrio Puerto. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Nossa paila marina da casa, premiada como a melhor do Barrio Puerto. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Notre paila marina maison, primée meilleure paila du Barrio Puerto. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Unsere Paila Marina des Hauses, ausgezeichnet als beste Paila im Barrio Puerto. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "La nostra paila marina della casa, premiata come la migliore del Barrio Puerto. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "本店招牌海鲜汤，荣获港口区（Barrio Puerto）最佳 paila marina。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Onze huis-paila marina, bekroond als beste paila van Barrio Puerto. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'sopa');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Caldillo de congrio', 'Caldo tradicional chileno de congrio, el plato al que Pablo Neruda le escribió una oda. Incluye consomé o ensalada, pebre y pan.', 12000, '{}', 7, false, '{"en": {"descripcion": "Traditional Chilean kingklip (congrio) broth, the dish Pablo Neruda wrote an ode to. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Caldo tradicional chileno de congro, o prato que inspirou uma ode de Pablo Neruda. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Bouillon chilien traditionnel de congre, le plat auquel Pablo Neruda a dédié une ode. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Traditionelle chilenische Kingklip-Suppe (Congrio), der Pablo Neruda eine Ode widmete. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Brodo tradizionale cileno di congrio, il piatto a cui Pablo Neruda dedicò un''ode. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "智利传统康吉鳗鱼汤，聂鲁达曾为它写过一首颂歌。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Traditionele Chileense bouillon van kingklip (congrio), het gerecht waar Pablo Neruda een ode aan schreef. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'sopa');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Chupe de mariscos', 'Mariscos en salsa cremosa gratinada con queso, un clásico chileno. Incluye consomé o ensalada, pebre y pan.', 12000, '{}', 8, false, '{"en": {"descripcion": "Seafood in a creamy sauce, gratinated with cheese, a Chilean classic. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Frutos do mar em molho cremoso gratinado com queijo, um clássico chileno. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Fruits de mer en sauce crémeuse gratinée au fromage, un classique chilien. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Meeresfrüchte in cremiger Sauce, mit Käse überbacken – ein chilenischer Klassiker. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Frutti di mare in salsa cremosa gratinati al formaggio, un classico cileno. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "芝士焗奶油海鲜，智利经典菜。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Zeevruchten in romige saus, gegratineerd met kaas, een Chileense klassieker. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'jaiba');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Bistec, chuleta o filete de pollo a lo pobre', 'A lo pobre: con papas fritas, cebolla frita y huevos fritos. Elige bistec, chuleta o filete de pollo. Incluye consomé o ensalada, pebre y pan.', 12000, '{}', 9, false, '{"en": {"descripcion": "\"A lo pobre\": with French fries, fried onions and fried eggs. Choose beef steak, pork chop or chicken fillet. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "\"A lo pobre\": com batatas fritas, cebola frita e ovos fritos. Escolha bife, costeleta ou filé de frango. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "« A lo pobre » : avec frites, oignons frits et œufs au plat. Au choix : steak, côtelette ou filet de poulet. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "„A lo pobre“: mit Pommes frites, gebratenen Zwiebeln und Spiegeleiern. Wahlweise Rindersteak, Kotelett oder Hähnchenfilet. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "\"A lo pobre\": con patatine fritte, cipolla fritta e uova fritte. Scegli bistecca, braciola o filetto di pollo. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "“穷人式”：配薯条、炸洋葱和煎蛋。可选牛排、猪排或鸡柳。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "\"A lo pobre\": met friet, gebakken ui en spiegeleieren. Kies biefstuk, karbonade of kipfilet. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Carne", "min": 1, "max": 1, "valores": [{"nombre": "Bistec", "precio": 0}, {"nombre": "Chuleta", "precio": 0}, {"nombre": "Filete de pollo", "precio": 0}]}, {"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'huevo');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Lomo a lo pobre', 'Lomo con papas fritas, cebolla frita y huevos fritos. Incluye consomé o ensalada, pebre y pan.', 15000, '{}', 10, false, '{"en": {"descripcion": "Beef tenderloin with French fries, fried onions and fried eggs. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Lombo com batatas fritas, cebola frita e ovos fritos. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Filet de bœuf avec frites, oignons frits et œufs au plat. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Rinderlende mit Pommes frites, gebratenen Zwiebeln und Spiegeleiern. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Lombo di manzo con patatine fritte, cipolla fritta e uova fritte. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "牛里脊配薯条、炸洋葱和煎蛋。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Ossenhaas met friet, gebakken ui en spiegeleieren. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'carne');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Menú del día', 2, '{"en": {"nombre": "Menu of the day"}, "pt": {"nombre": "Menu do dia"}, "fr": {"nombre": "Menu du jour"}, "de": {"nombre": "Tagesmenü"}, "it": {"nombre": "Menù del giorno"}, "zh": {"nombre": "今日套餐"}, "nl": {"nombre": "Dagmenu"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Menú del día', 'Pregunta por el menú y el postre del día. Incluye consomé o ensalada, pebre y pan.', 6000, '{}', 0, true, '{"en": {"descripcion": "Ask about today''s menu and dessert. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Pergunte pelo menu e pela sobremesa do dia. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Demandez le menu et le dessert du jour. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Fragen Sie nach dem Tagesmenü und dem Dessert des Tages. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Chiedi il menù e il dolce del giorno. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "请询问今日菜单和甜点。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Vraag naar het dagmenu en het dessert van de dag. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'plato');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Menú vegetariano', 'Pregunta por el menú vegetariano del día. Incluye consomé o ensalada, pebre y pan.', 6000, '{"vegetariano"}', 1, false, '{"en": {"descripcion": "Ask about today''s vegetarian menu. Includes consommé or salad, pebre and bread."}, "pt": {"descripcion": "Pergunte pelo menu vegetariano do dia. Inclui consomê ou salada, pebre e pão."}, "fr": {"descripcion": "Demandez le menu végétarien du jour. Avec consommé ou salade, pebre et pain."}, "de": {"descripcion": "Fragen Sie nach dem vegetarischen Tagesmenü. Mit Kraftbrühe oder Salat, Pebre und Brot."}, "it": {"descripcion": "Chiedi il menù vegetariano del giorno. Con consommé o insalata, pebre e pane."}, "zh": {"descripcion": "请询问今日素食菜单。 附清汤或沙拉、智利辣酱（pebre）和面包。"}, "nl": {"descripcion": "Vraag naar het vegetarische dagmenu. Met bouillon of salade, pebre en brood."}}'::jsonb, '[{"nombre": "Acompañamiento", "min": 1, "max": 1, "valores": [{"nombre": "Consomé", "precio": 0}, {"nombre": "Ensalada", "precio": 0}]}]'::jsonb, 'ensalada');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Para compartir', 3, '{"en": {"nombre": "To share"}, "pt": {"nombre": "Para compartilhar"}, "fr": {"nombre": "À partager"}, "de": {"nombre": "Zum Teilen"}, "it": {"nombre": "Da condividere"}, "zh": {"nombre": "分享拼盘"}, "nl": {"nombre": "Om te delen"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Chorrillana', 'Montaña de papas fritas con cebolla y huevo frito, para compartir. Elige de carne, pollo, marisco o vegetariana.', 15000, '{}', 0, true, '{"en": {"descripcion": "A mountain of French fries topped with meat, onions and fried eggs, to share. Choose beef, chicken, seafood or vegetarian."}, "pt": {"descripcion": "Batatas fritas com carne, cebola e ovo frito, para compartilhar. Escolha carne, frango, frutos do mar ou vegetariana."}, "fr": {"descripcion": "Frites garnies de viande, d''oignons et d''œufs au plat, à partager. Au choix : bœuf, poulet, fruits de mer ou végétarienne."}, "de": {"descripcion": "Pommes frites mit Fleisch, Zwiebeln und Spiegelei zum Teilen. Wahlweise Rind, Hähnchen, Meeresfrüchte oder vegetarisch."}, "it": {"descripcion": "Patatine fritte con carne, cipolla e uovo fritto, da condividere. Scegli manzo, pollo, frutti di mare o vegetariana."}, "zh": {"descripcion": "薯条配肉、洋葱和煎蛋，适合分享。可选牛肉、鸡肉、海鲜或素食。"}, "nl": {"descripcion": "Friet met vlees, ui en spiegelei, om te delen. Kies rund, kip, zeevruchten of vegetarisch."}}'::jsonb, '[{"nombre": "Tipo", "min": 1, "max": 1, "valores": [{"nombre": "Carne", "precio": 0}, {"nombre": "Pollo", "precio": 0}, {"nombre": "Marisco", "precio": 0}, {"nombre": "Vegetariana", "precio": 0}]}]'::jsonb, 'papas');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Papas fritas', 'Porción de papas fritas, normal o grande.', 4000, '{}', 1, false, '{"en": {"descripcion": "French fries, regular or large."}, "pt": {"descripcion": "Porção de batatas fritas, normal ou grande."}, "fr": {"descripcion": "Portion de frites, normale ou grande."}, "de": {"descripcion": "Pommes frites, normal oder groß."}, "it": {"descripcion": "Porzione di patatine fritte, normale o grande."}, "zh": {"descripcion": "薯条，普通份或大份。"}, "nl": {"descripcion": "Portie friet, normaal of groot."}}'::jsonb, '[{"nombre": "Tamaño", "min": 1, "max": 1, "valores": [{"nombre": "Normal", "precio": 0}, {"nombre": "Grande", "precio": 3000}]}]'::jsonb, 'papas');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Promos especiales', 4, '{"en": {"nombre": "Special deals"}, "pt": {"nombre": "Promoções especiais"}, "fr": {"nombre": "Formules spéciales"}, "de": {"nombre": "Sonderangebote"}, "it": {"nombre": "Promozioni speciali"}, "zh": {"nombre": "特惠套餐"}, "nl": {"nombre": "Speciale aanbiedingen"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Promo especial 1', '2 filetes de pollo con papas fritas, ensalada del día, 1 empanada y 1 bebida express.', 16000, '{}', 0, true, '{"en": {"descripcion": "2 chicken fillets with French fries, salad of the day, 1 empanada and 1 small soft drink."}, "pt": {"descripcion": "2 filés de frango com batatas fritas, salada do dia, 1 empanada e 1 refrigerante pequeno."}, "fr": {"descripcion": "2 filets de poulet avec frites, salade du jour, 1 empanada et 1 petite boisson."}, "de": {"descripcion": "2 Hähnchenfilets mit Pommes frites, Tagessalat, 1 Empanada und 1 kleines Erfrischungsgetränk."}, "it": {"descripcion": "2 filetti di pollo con patatine fritte, insalata del giorno, 1 empanada e 1 bibita piccola."}, "zh": {"descripcion": "2块鸡柳配薯条、每日沙拉、1个馅饼和1瓶小瓶饮料。"}, "nl": {"descripcion": "2 kipfilets met friet, salade van de dag, 1 empanada en 1 klein frisdrankje."}}'::jsonb, '[]'::jsonb, 'pollo');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Promo especial 2', '10 calugas, papas fritas, 1 empanada camarón queso, 1 empanada de marisco y 1 bebida express.', 19000, '{}', 1, true, '{"en": {"descripcion": "10 fried hake strips, French fries, 1 shrimp & cheese empanada, 1 seafood empanada and 1 small soft drink."}, "pt": {"descripcion": "10 iscas de peixe, batatas fritas, 1 empanada de camarão com queijo, 1 empanada de frutos do mar e 1 refrigerante pequeno."}, "fr": {"descripcion": "10 bâtonnets de poisson, frites, 1 empanada crevettes-fromage, 1 empanada fruits de mer et 1 petite boisson."}, "de": {"descripcion": "10 Fischstücke, Pommes frites, 1 Empanada Garnele & Käse, 1 Empanada mit Meeresfrüchten und 1 kleines Erfrischungsgetränk."}, "it": {"descripcion": "10 bocconcini di pesce, patatine fritte, 1 empanada gamberi e formaggio, 1 empanada ai frutti di mare e 1 bibita piccola."}, "zh": {"descripcion": "10块炸鱼条、薯条、1个虾仁芝士馅饼、1个海鲜馅饼和1瓶小瓶饮料。"}, "nl": {"descripcion": "10 visreepjes, friet, 1 empanada garnaal & kaas, 1 empanada met zeevruchten en 1 klein frisdrankje."}}'::jsonb, '[]'::jsonb, 'pescado');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Brebajes', 5, '{"en": {"nombre": "Drinks"}, "pt": {"nombre": "Bebidas"}, "fr": {"nombre": "Boissons"}, "de": {"nombre": "Getränke"}, "it": {"nombre": "Bevande"}, "zh": {"nombre": "饮品"}, "nl": {"nombre": "Dranken"}}'::jsonb, 'Barra') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Cola de mono casero · copa', 'Hecho en casa y premiado como el mejor del Barrio Puerto. Por copa.', 2000, '{"recomendado"}', 0, false, '{"en": {"descripcion": "Homemade cola de mono (Chilean coffee-milk liqueur), awarded best in Barrio Puerto. By the glass."}, "pt": {"descripcion": "Cola de mono caseiro (licor chileno de café e leite), premiado como o melhor do Barrio Puerto. Por taça."}, "fr": {"descripcion": "Cola de mono maison (liqueur chilienne café-lait), primé meilleur du Barrio Puerto. Au verre."}, "de": {"descripcion": "Hausgemachter Cola de Mono (chilenischer Kaffee-Milch-Likör), ausgezeichnet als bester im Barrio Puerto. Pro Glas."}, "it": {"descripcion": "Cola de mono fatto in casa (liquore cileno di caffè e latte), premiato come il migliore del Barrio Puerto. Al bicchiere."}, "zh": {"descripcion": "自制“猴尾酒”（智利咖啡牛奶利口酒），荣获港口区最佳。按杯。"}, "nl": {"descripcion": "Huisgemaakte cola de mono (Chileense koffie-melklikeur), bekroond als beste van Barrio Puerto. Per glas."}}'::jsonb, '[]'::jsonb, 'batido');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Cola de mono casero · botella', 'Hecho en casa y premiado como el mejor del Barrio Puerto. Botella.', 6000, '{"recomendado"}', 1, false, '{"en": {"descripcion": "Homemade cola de mono (Chilean coffee-milk liqueur), awarded best in Barrio Puerto. Bottle."}, "pt": {"descripcion": "Cola de mono caseiro (licor chileno de café e leite), premiado como o melhor do Barrio Puerto. Garrafa."}, "fr": {"descripcion": "Cola de mono maison (liqueur chilienne café-lait), primé meilleur du Barrio Puerto. Bouteille."}, "de": {"descripcion": "Hausgemachter Cola de Mono (chilenischer Kaffee-Milch-Likör), ausgezeichnet als bester im Barrio Puerto. Flasche."}, "it": {"descripcion": "Cola de mono fatto in casa (liquore cileno di caffè e latte), premiato come il migliore del Barrio Puerto. Bottiglia."}, "zh": {"descripcion": "自制“猴尾酒”（智利咖啡牛奶利口酒），荣获港口区最佳。整瓶。"}, "nl": {"descripcion": "Huisgemaakte cola de mono (Chileense koffie-melklikeur), bekroond als beste van Barrio Puerto. Fles."}}'::jsonb, '[]'::jsonb, 'servir');
